package android.system;
import java.io.*;import java.nio.file.*;import java.util.*;
/** Linux file bytes/mode/link operations; Android UID and directory-fsync are explicit host boundaries. */
public final class Os {
 public static String failFsyncPath,failFsyncLeafPrefix;public static int failFsyncOccurrence=1;public static final List<String> syncLog=new ArrayList<String>();
 private static final Map<FileDescriptor,Open> OPEN=Collections.synchronizedMap(new IdentityHashMap<FileDescriptor,Open>());
 private static final Map<String,Integer> UIDS=new LinkedHashMap<String,Integer>();private static final Map<String,Integer> SYNCS=new HashMap<String,Integer>();
 private static final class Open {final Path path;final RandomAccessFile file;final int flags;Open(Path p,RandomAccessFile f,int flags){path=p;file=f;this.flags=flags;}}
 public static synchronized void fixtureUidRoot(String path,int uid){UIDS.put(path,uid);}public static synchronized void resetFaults(){failFsyncPath=null;failFsyncLeafPrefix=null;failFsyncOccurrence=1;SYNCS.clear();syncLog.clear();}
 public static StructStat lstat(String s)throws Exception{Path p=Paths.get(s);if(!Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new ErrnoException("lstat",2);Map<String,Object>a=Files.readAttributes(p,"unix:*",LinkOption.NOFOLLOW_LINKS);StructStat r=new StructStat();r.st_dev=((Number)a.get("dev")).longValue();r.st_ino=((Number)a.get("ino")).longValue();r.st_size=((Number)a.get("size")).longValue();r.st_nlink=((Number)a.get("nlink")).longValue();r.st_uid=((Number)a.get("uid")).intValue();r.st_gid=((Number)a.get("gid")).intValue();s=p.toAbsolutePath().toString();synchronized(Os.class){for(Map.Entry<String,Integer> e:UIDS.entrySet())if(s.equals(e.getKey())||s.startsWith(e.getKey()+"/"))r.st_uid=r.st_gid=e.getValue();}r.st_mode=((Number)a.get("mode")).intValue();r.st_mtime=((java.nio.file.attribute.FileTime)a.get("lastModifiedTime")).toMillis()/1000;r.st_ctime=((java.nio.file.attribute.FileTime)a.get("ctime")).toMillis()/1000;return r;}
 public static StructStat fstat(FileDescriptor fd)throws Exception{Open o=OPEN.get(fd);if(o==null)throw new IOException("untracked host descriptor");return lstat(o.path.toString());}
 public static FileDescriptor open(String s,int flags,int mode)throws Exception{Path p=Paths.get(s);if(Files.isSymbolicLink(p))throw new ErrnoException("nofollow",40);if((flags&OsConstants.O_EXCL)!=0&&Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new ErrnoException("exists",17);if((flags&OsConstants.O_CREAT)!=0){Files.createFile(p);chmod(s,mode);}if(!Files.exists(p))throw new ErrnoException("open",2);if(Files.isDirectory(p)){FileDescriptor fd=new FileDescriptor();OPEN.put(fd,new Open(p,null,flags));return fd;}RandomAccessFile f=new RandomAccessFile(s,(flags&OsConstants.O_WRONLY)!=0?"rw":"r");FileDescriptor fd=f.getFD();OPEN.put(fd,new Open(p,f,flags));return fd;}
 public static void close(FileDescriptor fd)throws Exception{Open o=OPEN.remove(fd);if(o!=null&&o.file!=null)o.file.close();}
 public static void chmod(String s,int mode)throws Exception{Files.setAttribute(Paths.get(s),"unix:mode",mode);}public static void mkdir(String s,int mode)throws Exception{Files.createDirectory(Paths.get(s));chmod(s,mode);}
 public static int write(FileDescriptor fd,byte[] b,int at,int n)throws Exception{OPEN.get(fd).file.write(b,at,n);return n;}
 public static int read(FileDescriptor fd,byte[] b,int at,int n)throws Exception{int got=OPEN.get(fd).file.read(b,at,n);return got<0?0:got;}
 public static int fcntlInt(FileDescriptor fd,int cmd,int ignored)throws Exception{if(cmd!=OsConstants.F_GETFL)throw new IOException("unsupported fcntl");return OPEN.get(fd).flags;}
 public static long lseek(FileDescriptor fd,long offset,int whence)throws Exception{if(whence!=OsConstants.SEEK_CUR||offset!=0)throw new IOException("host only current seek");return OPEN.get(fd).file.getFilePointer();}
 public static synchronized void fsync(FileDescriptor fd)throws Exception{Open o=OPEN.get(fd);if(o==null)throw new IOException("unknown sync descriptor");String s=o.path.toString();syncLog.add(s);int count=SYNCS.containsKey(s)?SYNCS.get(s)+1:1;SYNCS.put(s,count);if((s.equals(failFsyncPath)&&count==failFsyncOccurrence)||(failFsyncLeafPrefix!=null&&o.path.getFileName().toString().startsWith(failFsyncLeafPrefix)))throw new IOException("injected fsync failure");if(o.file!=null&&fd.valid())fd.sync();}
}